import { ButtonItem, ConfirmModal, Field, PanelSection, PanelSectionRow, TextField, ToggleField, showModal } from "@decky/ui";
import { useEffect, useRef, useState } from "react";
import { detectSdcard, formatSdcard, installSamba, setShare, shareStatus } from "../backend";
import type { SdcardInfo, ShareStatus } from "../types";

function cardSummary(card: SdcardInfo | null) {
  if (!card) return "Checking…";
  if (!card.present) return "No SD card detected";
  if (card.bootDisk) return "Booted from this card - formatting disabled";
  const size = card.sizeBytes ? `${(card.sizeBytes / 1e9).toFixed(1)} GB` : "";
  const state = card.fstype === "ext4" ? (card.mountpoint ? "mounted" : "") : "not formatted for Steam";
  return [card.label || "unlabeled", size, card.fstype || "no filesystem", state].filter(Boolean).join(" · ");
}

// closeModal must not be forwarded to ConfirmModal: its OK handler would close the dialog
// at once, and it has to stay open until the format finishes.
function FormatConfirmModal({ summary, onConfirm, closeModal }: { summary: string; onConfirm: () => Promise<void>; closeModal?: () => void }) {
  const [text, setText] = useState("");
  const [running, setRunning] = useState(false);
  const armedRef = useRef(false);
  const runningRef = useRef(false);
  armedRef.current = text.trim().toLowerCase() === "format";
  runningRef.current = running;
  const start = async () => {
    if (!armedRef.current || runningRef.current) return;
    setRunning(true);
    await onConfirm();
    closeModal?.();
  };
  return (
    <ConfirmModal
      strTitle="Format SD Card"
      strDescription={
        running
          ? "Formatting… This can take a minute. Do not remove the card."
          : `This erases ALL data on the card (${summary}) and formats it for Steam. Type "format" and press Enter to confirm.`
      }
      strOKButtonText={running ? "Formatting…" : "Erase and Format"}
      bDestructiveWarning={true}
      bOKDisabled={!armedRef.current || running}
      bCancelDisabled={running}
      bDisableBackgroundDismiss={true}
      bHideCloseIcon={true}
      onCancel={() => {
        if (!runningRef.current) closeModal?.();
      }}
      onOK={start}
    >
      {!running ? (
        <TextField
          value={text}
          focusOnMount={true}
          onChange={(event) => setText(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter") start();
          }}
        />
      ) : null}
    </ConfirmModal>
  );
}

// The share is guest-writable and covers the whole home folder, so the trade is spelled out
// rather than buried: same warning the Pocknix Tools menu shows before it flips the switch.
function ShareConfirmModal({ onConfirm, closeModal }: { onConfirm: () => Promise<void>; closeModal?: () => void }) {
  const [running, setRunning] = useState(false);
  const runningRef = useRef(false);
  runningRef.current = running;
  const start = async () => {
    if (runningRef.current) return;
    setRunning(true);
    await onConfirm();
    closeModal?.();
  };
  return (
    <ConfirmModal
      strTitle="Share Files Over The Network"
      strDescription={
        running
          ? "Starting…"
          : "Anyone on the same network can read and write every file in your home folder - games, saves and emulator settings, but also your Steam login and SSH keys. There is no password. Only turn this on at home."
      }
      strOKButtonText={running ? "Starting…" : "Turn On Sharing"}
      bDestructiveWarning={true}
      bOKDisabled={running}
      bCancelDisabled={running}
      bDisableBackgroundDismiss={true}
      onCancel={() => {
        if (!runningRef.current) closeModal?.();
      }}
      onOK={start}
    />
  );
}

function FileSharing() {
  const [share, setShareState] = useState<ShareStatus | null>(null);
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState("");
  const busyRef = useRef(false);
  busyRef.current = busy;

  useEffect(() => {
    let cancelled = false;
    const refresh = async () => {
      if (busyRef.current) return;
      try {
        const next = await shareStatus();
        if (!cancelled && !busyRef.current) setShareState(next);
      } catch (error) {
        if (!cancelled) setStatus(String(error));
      }
    };
    refresh();
    const timer = window.setInterval(refresh, 5000);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, []);

  const run = async (action: () => Promise<ShareStatus>) => {
    if (busyRef.current) return;
    setBusy(true);
    setStatus("");
    try {
      setShareState(await action());
    } catch (error) {
      setStatus(String(error));
    } finally {
      setBusy(false);
    }
  };

  const summary = () => {
    if (status) return status;
    if (!share) return "Checking…";
    if (!share.installed) return "Samba is not installed (7.4 MB download)";
    if (share.on) return "On - open smb://pocknix.local and connect as Guest";
    return "Off - your home folder is not shared";
  };

  return (
    <PanelSection title="FILE SHARING">
      <Field label="Network share" description={summary()} />
      {share && !share.installed ? (
        <PanelSectionRow>
          <ButtonItem layout="below" disabled={busy} onClick={() => run(installSamba)}>
            {busy ? "Installing…" : "Install Samba"}
          </ButtonItem>
        </PanelSectionRow>
      ) : (
        <PanelSectionRow>
          <ToggleField
            label="Share my home folder"
            description="Drag files straight onto the device from another computer"
            checked={!!share?.on}
            disabled={busy || !share?.installed}
            onChange={(on: boolean) => {
              if (busyRef.current) return;
              if (on) showModal(<ShareConfirmModal onConfirm={() => run(() => setShare(true))} />);
              else run(() => setShare(false));
            }}
          />
        </PanelSectionRow>
      )}
    </PanelSection>
  );
}

export function Storage() {
  const [card, setCard] = useState<SdcardInfo | null>(null);
  const [label, setLabel] = useState("SDCARD");
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState("");
  const busyRef = useRef(false);
  busyRef.current = busy;

  useEffect(() => {
    let cancelled = false;
    const refresh = async () => {
      if (busyRef.current) return;
      try {
        const next = await detectSdcard();
        if (!cancelled && !busyRef.current) setCard(next);
      } catch (error) {
        if (!cancelled) setStatus(String(error));
      }
    };
    refresh();
    const timer = window.setInterval(refresh, 5000);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, []);

  const runFormat = async () => {
    if (busyRef.current) return;
    setBusy(true);
    setStatus("");
    try {
      const next = await formatSdcard(label);
      setCard(next);
    } catch (error) {
      setStatus(String(error));
    } finally {
      setBusy(false);
    }
  };
  const confirmFormat = () => showModal(<FormatConfirmModal summary={cardSummary(card)} onConfirm={runFormat} />);

  return (
    <>
    <PanelSection title="SD CARD">
      <Field label="Card" description={cardSummary(card)} />
      <PanelSectionRow>
        <TextField
          label="Label"
          value={label}
          disabled={busy || !!card?.bootDisk}
          onChange={(event) => setLabel(event.target.value.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 16))}
        />
      </PanelSectionRow>
      <PanelSectionRow>
        <ButtonItem layout="below" disabled={!card?.present || busy || !!card?.bootDisk} onClick={confirmFormat}>
          {busy ? "Formatting…" : "Format SD Card"}
        </ButtonItem>
      </PanelSectionRow>
      {status ? <Field label="" description={status} /> : null}
    </PanelSection>
    <FileSharing />
    </>
  );
}
